it('a native SDK search receipt supplies bound choices, H5 saves a pending selection, and the actual queue verifies it before continuing the same task',async()=>{
 const f=await fresh(),queue=new RunQueue(secret('QUEUE_DATABASE_URL')!,'choice-'+randomUUID());await queue.start();await queue.work(job=>f.runtime.advance(f.ctx,job.runId,undefined,undefined,job.generation));await queue.workSourceReplies(async job=>{await f.gateway.processSourceReply(f.ctx,job.replyId,job.generation);});let publishing=false;const timer=setInterval(()=>{if(publishing)return;publishing=true;void queue.publish(db,f.ctx).finally(()=>{publishing=false;});},100);timer.unref();const api=await createServer({config:config(),db:appDb,sessionSecret:randomBytes(32).toString('hex'),finalReader:f.gateway}),session=await api.sessions.create(f.ctx);
 try{await queue.publish(db,f.ctx);await expect.poll(f.state,{timeout:10000}).toMatchObject({status:'WAITING_USER',last_error:'SOURCE_CHOICE_REQUIRED'});const waiting=await f.state();expect(waiting.result).toContain(syntheticPath);expect(waiting.result).toContain(secondPath);expect(f.fixture.counts()).toMatchObject({searches:1,reads:0});expect(f.requests).toHaveLength(2);expect((await new TaskStore(appDb).get(f.ctx,f.taskId))!.status).toBe('ACTIVE');const view=(await api.app.inject({url:'/api/v1/tasks/'+f.taskId,headers:{cookie:'oa_session='+session.cookie}})).json().data.runs[0];expect(view.source_choice_options).toEqual([{index:1,label:syntheticPath+':1–1'},{index:2,label:secondPath+':1–1'}]);await expect(appDb.scope(f.ctx,c=>c.query('SELECT answer_ref FROM source_choice_replies'))).rejects.toMatchObject({code:'42501'});const key=randomUUID(),headers={cookie:'oa_session='+session.cookie,origin:config().APP_ORIGIN,'x-csrf-token':session.csrf,'idempotency-key':key},payload={reviewId:waiting.source_choice_id,text:'第二个'},response=await api.app.inject({method:'POST',url:'/api/v1/tasks/'+f.taskId+'/messages',headers,payload});expect(response.statusCode,response.payload).toBe(202);expect(response.json().data.status).toBe('PENDING_SOURCE_CHECK');await expect.poll(f.state,{timeout:10000}).toMatchObject({status:'SUCCEEDED'});expect(f.fixture.counts()).toMatchObject({searches:1,reads:1});expect(f.requests).toHaveLength(4);expect((await f.state()).result).toContain(secondPath);expect((await f.state()).result).toContain('0.9');expect((await f.state()).result).not.toContain('0.5');const replied=await api.app.inject({method:'POST',url:'/api/v1/tasks/'+f.taskId+'/messages',headers,payload});expect(replied.statusCode).toBe(202);expect(replied.json().data.replyId).toBe(response.json().data.replyId);expect((await db.scope(f.ctx,c=>c.query('SELECT state FROM source_choice_replies WHERE run_id=$1',[f.runId]))).rows).toEqual([{state:'CONSUMED'}]);expect((await root.query('SELECT active_ms FROM runs WHERE id=$1',[f.runId])).rows[0].active_ms).not.toBe('0.000');}finally{clearInterval(timer);await queue.stop();await api.app.close();}
});
type SourceFixture=Awaited<ReturnType<typeof fresh>>;
async function waiting(f:SourceFixture){await f.runtime.advance(f.ctx,f.runId);expect(await f.state()).toMatchObject({status:'WAITING_USER',last_error:'SOURCE_CHOICE_REQUIRED'});return (await f.state()).source_choice_id as string;}
async function pending(f:SourceFixture,index='2'){const choiceId=await waiting(f),reply=await store.reply(f.ctx,f.taskId,choiceId,index,randomUUID());expect(reply).toMatchObject({status:'PENDING_SOURCE_CHECK'});if(!reply||!('replyId' in reply))throw Error('EXPECTED_SOURCE_REPLY');return {choiceId,replyId:reply.replyId};}
async function revokeSearch(f:SourceFixture){await root.query("UPDATE resource_grants SET revoked_at=clock_timestamp() WHERE tenant_id=$1 AND actor_id=$2 AND capability_id='company.code.search'",[f.ctx.tenantId,f.ctx.actorId]);}
async function replies(f:SourceFixture){return (await db.scope(f.ctx,c=>c.query('SELECT * FROM source_choice_replies WHERE run_id=$1 ORDER BY created_at,id',[f.runId]))).rows;}
function callback(f:SourceFixture,text:string,change:Record<string,unknown>={}){const id=randomUUID();return {...f.event,headers:{...f.event.headers,messageId:id},data:JSON.stringify({...JSON.parse(f.event.data),msgId:id,text:{content:text},sessionWebhook:'https://oapi.dingtalk.com/robot/send?access_token=synthetic-source-choice-fresh',sessionWebhookExpiredTime:Date.now()+60000,...change})};}
