 const f=await fresh(),id=await waiting(f),ingress=new DingTalkIngress(db,vault,{tenantId:f.ctx.tenantId,...f.binding}),event=callback(f,'继续任务 '+f.taskId+' '+id.replaceAll('-','').slice(0,8)+'：3');
 const response=(await ingress.acceptTrustedCallback(event))!;expect(response.taskId).not.toBe(f.taskId);expect(await ingress.acceptTrustedCallback(event)).toMatchObject({taskId:response.taskId,duplicate:true});expect(await replies(f)).toHaveLength(0);expect(await f.state()).toMatchObject({status:'WAITING_USER',source_reply_pending:false});expect(f.requests).toHaveLength(2);
 const receipt=(await new TaskStore(appDb).get(f.ctx,response.taskId))!;expect(receipt.runs[0]).toMatchObject({status:'PARTIAL',last_error:'CLARIFICATION_NOT_RESUMED'});expect((await db.scope(f.ctx,c=>c.query("SELECT id FROM outbox WHERE kind='SOURCE_REPLY'"))).rowCount).toBe(0);
