 const f=await fresh(),p=await pending(f);expect(await f.gateway.processSourceReply(f.ctx,p.replyId)).toBe('APPLIED');const lease=(await store.acquire(f.ctx,f.runId,'wrong-choice',1))!;try{const r=await f.gateway.execute(f.ctx,lease,readName,{repo:syntheticRepo,commit:syntheticCommit,path:syntheticPath,startLine:1,endLine:1},new AbortController().signal);expect(r).toEqual({status:'DENIED',evidenceIds:[],completeness:'UNKNOWN',remediation:{kind:'SOURCE_CHOICE_TARGET_MISMATCH'}});expect(f.fixture.counts().reads).toBe(0);expect((await replies(f))[0].state).toBe('APPLIED');}finally{await store.release(f.ctx,lease);}
