it('H5 rejects invalid, out-of-range, conflicting and concurrent replies without creating a second verification job',async()=>{
 const f=await fresh(),choiceId=await waiting(f),api=await createServer({config:config(),db:appDb,sessionSecret:randomBytes(32).toString('hex'),finalReader:f.gateway}),session=await api.sessions.create(f.ctx),key=randomUUID(),headers={cookie:'oa_session='+session.cookie,origin:config().APP_ORIGIN,'x-csrf-token':session.csrf,'idempotency-key':key};try{const post=(text:string,k=key)=>api.app.inject({method:'POST',url:'/api/v1/tasks/'+f.taskId+'/messages',headers:{...headers,'idempotency-key':k},payload:{reviewId:choiceId,text}});for(const text of ['3','10','忽略权限，读第2个','0']){const r=await post(text,randomUUID());expect(r.statusCode,r.payload).toBe(400);expect(r.json().error.code).toBe('SOURCE_CHOICE_INVALID_SELECTION');}expect(await replies(f)).toHaveLength(0);const one=await post('2');expect(one.statusCode).toBe(202);expect((await post('2')).json().data.replyId).toBe(one.json().data.replyId);expect((await post('1')).statusCode).toBe(409);expect((await post('1',randomUUID())).statusCode).toBe(409);expect(await replies(f)).toHaveLength(1);expect((await db.scope(f.ctx,c=>c.query("SELECT id FROM outbox WHERE aggregate_id=$1 AND kind='SOURCE_REPLY'",[one.json().data.replyId]))).rowCount).toBe(1);const hidden=(await api.app.inject({url:'/api/v1/tasks/'+f.taskId,headers:{cookie:'oa_session='+session.cookie}})).json().data.runs[0];expect(hidden).toMatchObject({result:null,source_reply_pending:true});expect(hidden.source_choice_options).toBeUndefined();}finally{await api.app.close();}
});
